// ===== passive hover + idle-refresh service (needs_hover) ==========
// Port of mpynode/_common/{hover_tracker,draw_refresh}.py. One
// session 30fps timer casts the cursor ray to find the hovered
// locator (self.hovered) and redraws auto_refresh nodes so the tween
// keeps advancing. Stored vars persist in a file-static per-node map.
namespace {
struct CircularTextTween {
    char _unused;  // no stored vars; keep the type non-empty
};
static std::map<unsigned, CircularTextTween> g_tween;            // per-node cross-frame state
static std::map<unsigned, MObjectHandle> g_handles;     // hash -> handle
static std::map<unsigned, std::vector<MPoint> > g_hoverTris;  // precise-hover soup (local space)
static std::set<unsigned> g_autoRefresh;                // nodes wanting idle redraw
static std::map<unsigned, MCallbackId> g_removalCbs;    // per-node delete callbacks
static bool          g_hoverValid = false;
static unsigned      g_hoverHash  = 0;
static MObjectHandle g_hoverHandle;
static MCallbackId   g_timerId = 0;
static double        g_lastDirtyT = -1.0;  // wall time of the last idle-redraw request (-1 = never)
static double        g_cpuAtDirty = 0.0;   // main-thread CPU seconds at that request
static double        g_lastRedraw = 0.0;   // CPU seconds the last request turned out to cost
static std::vector<MCallbackId> g_sceneCbs;
static bool          g_started = false;

static double _wallClock() {
    using namespace std::chrono;
    static const steady_clock::time_point t0 = steady_clock::now();
    return duration_cast<duration<double> >(steady_clock::now() - t0).count();
}
static double _epochClock() {
    // self.wallclock: seconds since the epoch -- the same clock and ORIGIN as
    // Python's time.time(), so a compiled and an interpreted gizmo side by
    // side sit at the same phase, not just the same speed.
    using namespace std::chrono;
    return duration_cast<duration<double> >(system_clock::now().time_since_epoch()).count();
}
static double _threadCpu() {
    // CPU seconds consumed by THIS (the main) thread. An idle main thread
    // consumes none, so the CPU spent since our last request is what
    // servicing it cost -- evaluation, prepareForDraw and draw -- with no
    // dependence on when Maya delivers its events.
#ifdef _WIN32
    FILETIME _c, _e, _k, _u;
    if (!GetThreadTimes(GetCurrentThread(), &_c, &_e, &_k, &_u)) return 0.0;
    const unsigned long long _kt = ((unsigned long long)_k.dwHighDateTime << 32) | _k.dwLowDateTime;
    const unsigned long long _ut = ((unsigned long long)_u.dwHighDateTime << 32) | _u.dwLowDateTime;
    return (double)(_kt + _ut) * 1e-7;
#else
    struct timespec _ts;
    if (clock_gettime(CLOCK_THREAD_CPUTIME_ID, &_ts) != 0) return 0.0;
    return (double)_ts.tv_sec + (double)_ts.tv_nsec * 1e-9;
#endif
}
static bool _isHovered(unsigned hash) { return g_hoverValid && g_hoverHash == hash; }
static void _registerNode(unsigned hash, const MObject& node) { g_handles[hash] = MObjectHandle(node); }
static void _setHoverTris(unsigned hash, const std::vector<MPoint>& t) {
    if (t.size() >= 3) g_hoverTris[hash] = t; else g_hoverTris.erase(hash);
}
static void _clearHoverTris(unsigned hash) { g_hoverTris.erase(hash); }

// Per-node delete teardown (mirrors draw_refresh.addNodePreRemovalCallback /
// hover_tracker.addNodeRemovedCallback): evict THIS node's state so it
// doesn't leak and -- crucially -- so a later node that reuses the freed
// MObjectHandle hashCode() starts from the lockstep defaults, not a dead
// node's stale tween (Python kept these on self, immune to hash reuse).
static void _onNodeRemoved(MObject& node, void*) {
    unsigned hash = MObjectHandle(node).hashCode();   // node still valid here
    g_tween.erase(hash); g_handles.erase(hash);
    g_hoverTris.erase(hash); g_autoRefresh.erase(hash);
    g_removalCbs.erase(hash);   // Maya releases the firing callback itself
    if (g_hoverValid && g_hoverHash == hash) { g_hoverValid = false; g_hoverHash = 0; }
}
static void _ensureNodeRemovalCb(unsigned hash, MObject node) {
    if (g_removalCbs.find(hash) != g_removalCbs.end()) return;
    MStatus s;  // addNodePreRemovalCallback wants a non-const MObject&
    MCallbackId id = MNodeMessage::addNodePreRemovalCallback(node, _onNodeRemoved, NULL, &s);
    if (s) g_removalCbs[hash] = id;
}

// Fan-triangulate the drawn polygon soups into ONE local-space triangle
// set for precise (ray-vs-triangle) hover -- matches the fill the draw
// renders. A soup qualifies on the node flag OR its own precise_hover.
static void _buildHoverTris(const CircularTextData& d, const MDagPath& dp, std::vector<MPoint>& out) {
    out.clear();
    for (size_t pi = 0; pi < d.polys.size(); ++pi) {
        const DrawPoly& pg = d.polys[pi];
        if (!(d.preciseHover || pg.preciseHover)) continue;
        if (pg.pts.empty() || pg.cnt.empty()) continue;
        std::vector<MPoint> P = pg.pts;
        if (pg.worldSpace) { MMatrix wInv = dp.inclusiveMatrixInverse();
            for (size_t i = 0; i < P.size(); ++i) P[i] = P[i] * wInv; }
        const size_t F = pg.cnt.size();
        std::vector<int> off(F, 0);
        for (size_t f = 1; f < F; ++f) off[f] = off[f-1] + pg.cnt[f-1];
        for (size_t f = 0; f < F; ++f) {
            int c = pg.cnt[f]; if (c < 3) continue;
            for (int k = 1; k + 1 < c; ++k) {
                int loc0 = off[f], lock = off[f] + k, lock1 = off[f] + k + 1;
                if (lock1 >= (int)pg.idx.size()) break;
                int i0 = pg.idx[loc0], i1 = pg.idx[lock], i2 = pg.idx[lock1];
                if (i0 < (int)P.size() && i1 < (int)P.size() && i2 < (int)P.size())
                    { out.push_back(P[i0]); out.push_back(P[i1]); out.push_back(P[i2]); }
            }
        }
    }
}

// Cursor ray in world space (HiDPI-corrected: Qt logical px -> physical).
static bool _cursorRay(MPoint& o, MVector& d) {
    MStatus st;
    M3dView view = M3dView::active3dView(&st);
    if (!st) return false;
    QWidget* w = view.widget();
    if (!w) return false;
    QPoint gp = QCursor::pos();
    QPoint local = w->mapFromGlobal(gp);
    double dpr = w->devicePixelRatioF();
    int x = (int)llround((double)local.x() * dpr);
    int y = (int)llround((double)view.portHeight() - (double)local.y() * dpr);
    if (x < 0 || y < 0 || x > view.portWidth() || y > view.portHeight()) return false;
    MPoint src; MVector vec;
    if (!view.viewToWorld((short)x, (short)y, src, vec)) return false;
    o = src; d = vec; return true;
}

static double _rayAABB(const MPoint& o, const MVector& d, const MPoint& lo, const MPoint& hi) {
    double tmin = 0.0, tmax = 1e30;
    for (int i = 0; i < 3; ++i) {
        double oi = o[i], di = d[i], loi = lo[i], hii = hi[i];
        if (fabs(di) < 1e-9) { if (oi < loi || oi > hii) return -1.0; }
        else {
            double t1 = (loi - oi) / di, t2 = (hii - oi) / di;
            if (t1 > t2) { double tmp = t1; t1 = t2; t2 = tmp; }
            if (t1 > tmin) tmin = t1;
            if (t2 < tmax) tmax = t2;
            if (tmin > tmax) return -1.0;
        }
    }
    return tmin;
}

// Vectorized-free Moller-Trumbore over the flat triangle soup (3 pts/tri).
static double _rayTris(const MPoint& o, const MVector& d, const std::vector<MPoint>& tris) {
    double best = 1e30; bool hit = false;
    for (size_t i = 0; i + 2 < tris.size(); i += 3) {
        MVector e1 = tris[i+1] - tris[i];
        MVector e2 = tris[i+2] - tris[i];
        MVector p = d ^ e2;
        double det = e1 * p;
        if (fabs(det) < 1e-9) continue;
        double inv = 1.0 / det;
        MVector tv = o - tris[i];
        double u = (tv * p) * inv;
        if (u < 0.0 || u > 1.0) continue;
        MVector q = tv ^ e1;
        double v = (d * q) * inv;
        if (v < 0.0 || u + v > 1.0) continue;
        double t = (e2 * q) * inv;
        if (t > 1e-6 && t < best) { best = t; hit = true; }
    }
    return hit ? best : -1.0;
}

// Update the hovered node; repaint any node whose hover state changed.
static void _setHovered(bool valid, unsigned hash, const MObject& obj) {
    if (g_hoverValid == valid && (!valid || g_hoverHash == hash)) return;
    MObjectHandle oldH = g_hoverHandle; bool oldValid = g_hoverValid;
    g_hoverValid = valid; g_hoverHash = hash;
    g_hoverHandle = valid ? MObjectHandle(obj) : MObjectHandle();
    if (oldValid && oldH.isValid()) MHWRender::MRenderer::setGeometryDrawDirty(oldH.object());
    if (valid && g_hoverHandle.isValid()) MHWRender::MRenderer::setGeometryDrawDirty(g_hoverHandle.object());
}

static void _poll(float, float, void*) {
    // idle redraw for auto_refresh nodes (cursor-independent so the tween
    // keeps animating after the cursor leaves the gizmo), THROTTLED on the
    // main thread's own CPU clock: the CPU it consumed since our last request
    // is what servicing that request cost (an idle thread consumes none), and
    // the next request waits 2x that, never less than a tick. Idle animation
    // therefore takes at most ~half the main thread however many locators are
    // in the scene (unthrottled, 100 nodes saturated it at 7.8 fps forever),
    // a cheap redraw keeps the full tick rate, and whatever else the user does
    // on the main thread backs the animation off. Earlier meters -- tick
    // lateness, VP2 render events -- depended on Maya's event ordering and
    // misread the cost. Port of draw_refresh.throttle_step.
    const double _now = _wallClock(), _period = 1.0 / 30.0, _cpu = _threadCpu();
    const double _spent = (g_lastDirtyT < 0.0) ? 0.0 : std::max(0.0, _cpu - g_cpuAtDirty);
    const double _wait = std::max(_period, 2.0 * _spent);
    if (!g_autoRefresh.empty() && (g_lastDirtyT < 0.0 || (_now - g_lastDirtyT) >= _wait)) {
        g_lastRedraw = _spent; g_lastDirtyT = _now; g_cpuAtDirty = _cpu;
        for (std::set<unsigned>::iterator it = g_autoRefresh.begin(); it != g_autoRefresh.end(); ++it) {
            std::map<unsigned, MObjectHandle>::iterator h = g_handles.find(*it);
            if (h != g_handles.end() && h->second.isValid())
                MHWRender::MRenderer::setGeometryDrawDirty(h->second.object());
        }
    }
    MPoint o; MVector d;
    if (!_cursorRay(o, d)) { _setHovered(false, 0, MObject::kNullObj); return; }
    double bestT = 1e30; bool found = false; unsigned bestHash = 0; MObject bestObj;
    for (MItDependencyNodes nit(MFn::kPluginLocatorNode); !nit.isDone(); nit.next()) {
        MObject node = nit.thisNode();
        MFnDependencyNode dn(node);
        if (dn.typeId() != CircularText::id) continue;   // only OUR generated type
        MDagPath dp; if (!MDagPath::getAPathTo(node, dp)) continue;
        unsigned hash = MObjectHandle(node).hashCode();
        std::map<unsigned, std::vector<MPoint> >::iterator ti = g_hoverTris.find(hash);
        if (ti != g_hoverTris.end()) {
            // precise: ray into local space then ray-vs-triangle
            MMatrix w2l = dp.inclusiveMatrixInverse();
            MPoint lo = o * w2l; MVector ld = d * w2l;
            double tt = _rayTris(lo, ld, ti->second);
            if (tt < 0.0 || tt >= bestT) continue;
            bestT = tt; found = true; bestHash = hash; bestObj = node;
        } else {
            MFnDagNode fnDag(dp);
            MBoundingBox bb = fnDag.boundingBox();
            bb.transformUsing(dp.inclusiveMatrix());
            double tt = _rayAABB(o, d, bb.min(), bb.max());
            if (tt < 0.0 || tt >= bestT) continue;
            bestT = tt; found = true; bestHash = hash; bestObj = node;
        }
    }
    _setHovered(found, bestHash, bestObj);
}

static void _onSceneEvent(void*) {
    g_hoverValid = false; g_hoverHash = 0; g_hoverHandle = MObjectHandle();
    g_lastDirtyT = -1.0; g_cpuAtDirty = 0.0; g_lastRedraw = 0.0;
    for (std::map<unsigned, MCallbackId>::iterator it = g_removalCbs.begin();
         it != g_removalCbs.end(); ++it) MMessage::removeCallback(it->second);
    g_removalCbs.clear();
    g_autoRefresh.clear(); g_hoverTris.clear(); g_handles.clear(); g_tween.clear();
}
static void _ensureHoverStarted() {
    if (g_started) return;
    if (MGlobal::mayaState() != MGlobal::kInteractive) { g_started = true; return; }  // batch: no-op, no retry
    MStatus s; MCallbackId id;
    id = MSceneMessage::addCallback(MSceneMessage::kBeforeNew, _onSceneEvent, NULL, &s);  if (s) g_sceneCbs.push_back(id);
    id = MSceneMessage::addCallback(MSceneMessage::kBeforeOpen, _onSceneEvent, NULL, &s); if (s) g_sceneCbs.push_back(id);
    id = MSceneMessage::addCallback(MSceneMessage::kMayaExiting, _onSceneEvent, NULL, &s);if (s) g_sceneCbs.push_back(id);
    g_timerId = MTimerMessage::addTimerCallback((float)(1.0/30.0), _poll, NULL, &s);
    if (s && g_timerId) { g_started = true; return; }
    // registration failed: undo the scene callbacks we just added so a
    // retry next draw doesn't double-register (g_started stays false).
    for (size_t i = 0; i < g_sceneCbs.size(); ++i) MMessage::removeCallback(g_sceneCbs[i]);
    g_sceneCbs.clear(); g_timerId = 0;
}
static void _stopHover() {
    if (g_timerId) { MMessage::removeCallback(g_timerId); g_timerId = 0; }
    for (size_t i = 0; i < g_sceneCbs.size(); ++i) MMessage::removeCallback(g_sceneCbs[i]);
    g_sceneCbs.clear(); _onSceneEvent(NULL); g_started = false;
}
}  // anonymous namespace

